const rows = $input.all().map(i => i.json).sort((a, b) => String(a.month).localeCompare(String(b.month)));
const N = x => Number(x || 0);
const calc = rows.map(r => { const opex = N(r.payroll) + N(r.rent) + N(r.marketing) + N(r.software) + N(r.other);
  const gp = N(r.revenue) - N(r.cost_of_sales); const np = gp - opex;
  return { month: r.month, revenue: N(r.revenue), gross_profit: gp, expenses: opex + N(r.cost_of_sales), net_profit: np, margin: N(r.revenue) ? np / N(r.revenue) : 0 }; });
const cur = calc[calc.length - 1], prev = calc[calc.length - 2];
const pct = (a, b) => b ? ((a - b) / b) * 100 : null;
const mom = { revenue_pct: pct(cur.revenue, prev.revenue), expenses_pct: pct(cur.expenses, prev.expenses), net_profit_pct: pct(cur.net_profit, prev.net_profit), margin_pts: (cur.margin - prev.margin) * 100 };
return [{ json: { client: 'Sample Client Ltd (fictional)', cur: cur, prev: prev, mom: mom, history: calc } }];

const d = $json;
const sys = 'You write a plain-English monthly summary for a small business owner who is not an accountant. 120-160 words. Use ONLY the numbers provided; never invent causes. Mention revenue, profit, margin, the biggest month-on-month change, and one question the owner should ask their bookkeeper. No jargon. No tax or investment advice.';
return { json: { body: { model: 'gpt-4o-mini', temperature: 0.2, messages: [ { role: 'system', content: sys }, { role: 'user', content: JSON.stringify({ cur: d.cur, prev: d.prev, mom: d.mom }) } ] } } };

const d = $('Calculate Metrics').first().json; const g = $json;
const summary = (g.content && g.content.parts && g.content.parts[0] && g.content.parts[0].text) || g.text || '';
const f = n => Number(n).toLocaleString('en-US', { maximumFractionDigits: 0 });
const pc = v => v === null ? 'n/a' : (v >= 0 ? '+' : '') + v.toFixed(1) + '%';
const bars = d.history.slice(-6).map(h => '<tr><td>' + h.month + '</td><td>' + f(h.revenue) + '</td><td>' + f(h.net_profit) + '</td><td>' + (h.margin * 100).toFixed(1) + '%</td></tr>').join('');
const html = '<html><body style="font-family:Helvetica,Arial;margin:40px;color:#222"><h1>Monthly Report: ' + d.cur.month + '</h1><p><i>' + d.client + '. Demo report on fictional data.</i></p>' +
'<table cellpadding="8"><tr><td><b>Revenue</b><br>' + f(d.cur.revenue) + '<br>' + pc(d.mom.revenue_pct) + ' vs prior month</td><td><b>Expenses</b><br>' + f(d.cur.expenses) + '<br>' + pc(d.mom.expenses_pct) + '</td><td><b>Net profit</b><br>' + f(d.cur.net_profit) + '<br>' + pc(d.mom.net_profit_pct) + '</td><td><b>Margin</b><br>' + (d.cur.margin * 100).toFixed(1) + '%<br>' + d.mom.margin_pts.toFixed(1) + ' pts</td></tr></table>' +
'<h2>In plain English</h2><p>' + summary.split('\n').join('<br>') + '</p><h2>Last 6 months</h2><table border="1" cellpadding="6" style="border-collapse:collapse"><tr><th>Month</th><th>Revenue</th><th>Net profit</th><th>Margin</th></tr>' + bars + '</table></body></html>';
const bin = await this.helpers.prepareBinaryData(Buffer.from(html, 'utf8'), 'index.html', 'text/html');
return { json: { month: d.cur.month, html_length: html.length, summary: summary }, binary: { files: bin } };
